* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
.wo-wrap {
  height: calc(var(--appsmith-ui-height) * 1px);
  width: calc(var(--appsmith-ui-width) * 1px);
  overflow: auto;
  background: var(--appsmith-theme-surfaceAltColor, #1e293b);
  border: 1px solid var(--appsmith-theme-borderColor, #334155);
  border-radius: 6px;
  font-family: system-ui;
}
.wo-hint { padding: 8px 14px; font-size: 12px; color: var(--appsmith-theme-textSecondaryColor, #94a3b8); border-bottom: 1px solid var(--appsmith-theme-borderColor, #334155); }
table.wo { border-collapse: collapse; width: max-content; min-width: 100%; background: var(--appsmith-theme-surfaceAltColor, #1e293b); }
table.wo th { padding: 10px 14px; font-size: 12px; font-weight: 700; color: var(--appsmith-theme-textStrongColor, #ffffff); white-space: nowrap; text-align: left; border-bottom: 2px solid var(--appsmith-theme-borderColor, #334155); background: var(--appsmith-theme-surfaceHoverColor, #26344b); position: sticky; top: 0; }
table.wo td { padding: 8px 14px; font-size: 12px; color: var(--appsmith-theme-textColor, #e2e8f0); border-bottom: 1px solid var(--appsmith-theme-borderColor, #334155); vertical-align: top; }
table.wo td.num { text-align: right; white-space: nowrap; }
table.wo td.nowrap { white-space: nowrap; }
table.wo td.warning { min-width: 360px; max-width: 560px; }
table.wo a { color: var(--appsmith-theme-linkColor, #60a5fa); text-decoration: underline; cursor: pointer; }
.empty { padding: 20px; color: var(--appsmith-theme-textSecondaryColor, #94a3b8); text-align: center; font-family: system-ui; }

srcDoc.js:
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function fmtAmt(v){ var n=Number(v); return isNaN(n)?'' : n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}); }
function render(model){
  var root = document.getElementById('root');
  if (!root) return;
  var rows = (model && model.rows) || [];
  if (!rows.length){ root.innerHTML = '<div class="empty">No data available</div>'; return; }
  var h = '<div class="wo-hint">\u24D8 To see the bill, click on the Pear ID.</div>';
  h += '<table class="wo"><thead><tr>';
  ['Total Amount','Invoice Date','Bill Warning','Pear ID','Location','Vendor','Utility Type','Resolved'].forEach(function(c){ h += '<th>' + c + '</th>'; });
  h += '</tr></thead><tbody>';
  rows.forEach(function(r){
    h += '<tr>';
    h += '<td class="num">' + fmtAmt(r.totalAmount) + '</td>';
    h += '<td class="nowrap">' + esc(r.invoiceDate) + '</td>';
    h += '<td class="warning">' + esc(r.warning) + '</td>';
    h += '<td class="nowrap"><a>' + esc(r.pearId) + '</a></td>';
    h += '<td class="nowrap">' + esc(r.location) + '</td>';
    h += '<td class="nowrap">' + esc(r.vendor) + '</td>';
    h += '<td class="nowrap">' + esc(r.utility) + '</td>';
    h += '<td class="nowrap">' + esc(r.resolved) + '</td>';
    h += '</tr>';
  });
  h += '</tbody></table>';
  root.innerHTML = h;
}
appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(function(m){ render(m); }); });

